// DeleteUniqueIndexCache 删除索引存在的缓存
func (b *BannerRepo) DeleteIndexCache(ctx context.Context, data ...*ai_boilerplate_model.Banner) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, b.cache.Key(CacheBannerByConditionPrefix))
	keys = append(keys, b.cache.Key(CacheBannerUnscopedByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[b.cache.Key(CacheBannerByIDPrefix, item.ID)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerUnscopedByIDPrefix, item.ID)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerByPlatformPrefix, item.Platform)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerUnscopedByPlatformPrefix, item.Platform)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerByPositionPrefix, item.Position)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerUnscopedByPositionPrefix, item.Position)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerBySortPrefix, item.Sort)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerUnscopedBySortPrefix, item.Sort)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerByStatusPrefix, item.Status)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerUnscopedByStatusPrefix, item.Status)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerByTenantIDPrefix, item.TenantID)] = struct{}{}
			KeyMap[b.cache.Key(CacheBannerUnscopedByTenantIDPrefix, item.TenantID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := b.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
